def _auto_dedup(prefix: str = "", suffix: str = "") -> frozenset[str]:
    """_BOOST_MAP에서 prefix/suffix 패턴으로 자동 dedup 그룹 생성."""
    return frozenset(
        tag
        for entries in _BOOST_MAP.values()
        for tag, score, _ in entries
        if score >= 0.02 and (
            (suffix and tag.endswith(suffix)) or
            (prefix and tag.startswith(prefix))
        )
    )


_POSITION_MUTEX: frozenset[str] = _auto_dedup(suffix="_position")
_TENTACLE_DEDUP: frozenset[str] = frozenset(
    tag for entries in _BOOST_MAP.values()
    for tag, score, _ in entries
    if score >= 0.02 and "tentacle" in tag
)
_WRITING_DEDUP: frozenset[str] = _auto_dedup(prefix="writing_on_")

