def _has_word_overlap(source: str, e621_tag: str) -> bool:
    """source와 e621_tag 사이에 의미 있는 단어 겹침이 있는지 확인."""
    src_words = set(source.replace("'s", "").replace("-", "_").split("_")) - _STOPWORDS
    tag_words = set(e621_tag.replace("-", "_").split("_")) - _STOPWORDS
    if src_words & tag_words:
        return True
    for sw in src_words:
        if len(sw) < 4:
            continue
        for tw in tag_words:
            if len(tw) < 4:
                continue
            if sw in tw or tw in sw:
                return True
    return False


# Pre-compute: 단독 source이고 단어 겹침 없는 output 태그 집합
# → 이 집합에 해당하면 _SINGLE_SOURCE_WHITELIST 체크 필요
_SINGLE_SOURCE_GATE: frozenset[str] = frozenset()  # placeholder


def _build_single_source_gate() -> frozenset[str]:
    """_BOOST_MAP에서 단독 source + 단어 겹침 없는 output 태그를 추출."""
    from collections import defaultdict
    reverse: dict[str, list[str]] = defaultdict(list)
    for source, entries in _BOOST_MAP.items():
        for e621_tag, score, _ in entries:
            if score >= DEFAULT_SCORE_FLOOR:
                reverse[e621_tag].append(source)

    gated: set[str] = set()
    for e621_tag, sources in reverse.items():
        if len(sources) == 1 and not _has_word_overlap(sources[0], e621_tag):
            gated.add(e621_tag)
    return frozenset(gated)


_SINGLE_SOURCE_GATE = _build_single_source_gate()
del _build_single_source_gate


def _check_single_source_gate(source_tag: str, e621_tag: str) -> bool:
    """단독 source gate. True=통과, False=차단."""
    if e621_tag not in _SINGLE_SOURCE_GATE:
        return True  # multi-source이거나 단어 겹침 있음 → 통과
    return (source_tag, e621_tag) in _SINGLE_SOURCE_WHITELIST


def _check_characteristic_filter(source_tag: str, e621_tag: str) -> bool:
    """Characteristic source에서 온 추천이 의미 있는지 확인.

    Returns:
        True = 통과 (추천 유지), False = 차단
    """
    if source_tag not in _CHARACTERISTIC_SOURCES:
        return True  # characteristic이 아니면 무조건 통과

    # 화이트리스트 체크
    wl = _CHAR_PAIR_WHITELIST.get(source_tag)
    if wl and e621_tag in wl:
        return True

    # 단어 교집합
    src_parts = set(source_tag.split("_"))
    tag_parts = set(e621_tag.split("_"))
    if src_parts & tag_parts:
        return True

    # 부분 문자열 (4자 이상)
    for sp in src_parts:
        if len(sp) < 4:
            continue
        for tp in tag_parts:
            if len(tp) < 4:
                continue
            if sp in tp or tp in sp:
                return True

    # 전체 문자열 substring
    src_clean = source_tag.replace("_", "")
    tag_clean = e621_tag.replace("_", "")
    if len(src_clean) >= 4 and src_clean in tag_clean:
        return True
    if len(tag_clean) >= 4 and tag_clean in src_clean:
        return True

    return False


# ═══════════════════════════════════════════════════════════════
# Filter Functions
# ═══════════════════════════════════════════════════════════════

def _check_anchor_gate(e621_tag: str, prompt_tags: frozenset[str]) -> bool:
    """keyword-split 기반 anchor gate. True=통과, False=차단."""
    parts = e621_tag.split("_")
    for kw in _ANCHOR_KEYWORDS:
        if kw in parts:
            if not (prompt_tags & _ANCHOR_GATES[kw]):
                return False
    return True


def _check_domain_gate(e621_tag: str, prompt_tags: frozenset[str]) -> bool:
    """직접 매칭 domain gate. True=통과, False=차단."""
    anchors = _DOMAIN_GATE_LOOKUP.get(e621_tag)
    if anchors is None:
        return True
    return bool(prompt_tags & anchors)


def _check_pair_block(e621_tag: str, source_tag: str) -> bool:
    """(output, source) pair block. True=차단."""
    blocked_sources = _PAIR_BLOCKLIST.get(e621_tag)
    return blocked_sources is not None and source_tag in blocked_sources


def _dedupe_group_results(
    sorted_all: list[tuple[str, tuple[float, str, str]]],
    mode: str = "stable",
) -> list[tuple[str, tuple[float, str, str]]]:
    """동의어 그룹 dedup.

    mode:
        "stable"  — 그룹당 최고 score 1개만 남긴다 (결정적).
        "confused" — 최소 1개 보장(가중 랜덤) + 나머지 score/total 확률로 추가.
    """
    if mode == "stable":
        seen_groups: set[int] = set()
        deduped: list[tuple[str, tuple[float, str, str]]] = []
        for e621_tag, payload in sorted_all:
            group_ids = _DEDUPE_GROUP_LOOKUP.get(e621_tag)
            if group_ids is not None:
                if any(group_idx in seen_groups for group_idx in group_ids):
                    continue
                seen_groups.update(group_ids)
            deduped.append((e621_tag, payload))
        return deduped

    # ── confused mode ──
    import random

    # 1) 그룹별 멤버 수집 (등장 순서 유지)
    group_members: dict[int, list[tuple[str, tuple[float, str, str]]]] = {}
    tag_group_map: dict[str, int] = {}  # tag → 대표 group_id
    ungrouped: list[tuple[str, tuple[float, str, str]]] = []

    for e621_tag, payload in sorted_all:
        group_ids = _DEDUPE_GROUP_LOOKUP.get(e621_tag)
        if group_ids is None:
            ungrouped.append((e621_tag, payload))
            continue
        gid = group_ids[0]
        tag_group_map[e621_tag] = gid
        if gid not in group_members:
            group_members[gid] = []
        group_members[gid].append((e621_tag, payload))

    # 2) 그룹별 확률적 선택
    selected_tags: set[str] = set()
    for gid, members in group_members.items():
        scores = [p[0] for _, p in members]
        total = sum(scores)
        if total <= 0:
            continue

        # Step A: 가중 랜덤으로 1개 보장
        r = random.random() * total
        cumul = 0.0
        for tag, payload in members:
            cumul += payload[0]
            if r < cumul:
                selected_tags.add(tag)
                break

        # Step B: 나머지 각각 P=score/total로 추가
        for tag, payload in members:
            if tag not in selected_tags and random.random() < payload[0] / total:
                selected_tags.add(tag)

    # 3) 원래 순서 유지하며 결과 조립
    deduped: list[tuple[str, tuple[float, str, str]]] = []
    for e621_tag, payload in sorted_all:
        if e621_tag in tag_group_map:
            if e621_tag in selected_tags:
                deduped.append((e621_tag, payload))
        else:
            deduped.append((e621_tag, payload))

    return deduped


# ═══════════════════════════════════════════════════════════════
# Public API
# ═══════════════════════════════════════════════════════════════

def recommend(
    prompt: str,
    *,
    top_n: int = DEFAULT_TOP_N,
    diversity_cap: int = DEFAULT_DIVERSITY_CAP,
    score_floor: float = DEFAULT_SCORE_FLOOR,
    mode: str = "stable",
) -> list[str]:
    """프롬프트 문자열에서 e621 부스트 태그 추천.

    Args:
        prompt: 쉼표 구분 태그 문자열 (e.g. "doggystyle, ahegao, sweat")
        top_n: 최대 결과 수
        diversity_cap: 카테고리별 최대 수 (0=무제한)
        score_floor: 최소 score 임계값 (기본 0.02)
        mode: "stable" (결정적 top-1) 또는 "confused" (확률적 다중 선택)

    Returns:
        추천 e621 태그 리스트 (underscore form, score 내림차순)
    """
    results = recommend_detailed(prompt, top_n=top_n, diversity_cap=diversity_cap,
                                 score_floor=score_floor, mode=mode)
    return [r[0] for r in results]


def recommend_detailed(
    prompt: str,
    *,
    top_n: int = DEFAULT_TOP_N,
    diversity_cap: int = DEFAULT_DIVERSITY_CAP,
    score_floor: float = DEFAULT_SCORE_FLOOR,
    mode: str = "stable",
) -> list[tuple[str, float, str, str]]:
    """프롬프트에서 e621 부스트 태그 추천 (상세 정보 포함).

    Args:
        mode: "stable" (결정적 top-1) 또는 "confused" (확률적 다중 선택)

    Returns:
        [(e621_tag, score, category, source_tag), ...] score 내림차순
    """
    tags = [t.strip().replace(" ", "_") for t in prompt.split(",") if t.strip()]
    tags_set = frozenset(tags)

    # Explicit context detection: 성적 맥락이 없으면 NSFW/Danger 카테고리 차단
    is_explicit = bool(tags_set & _EXPLICIT_INDICATORS)

    # Gender context detection: 성별 모순 태그 차단
    has_female = bool(tags_set & _FEMALE_INDICATORS)
    has_male = bool(tags_set & _MALE_INDICATORS)
    _gender_block: frozenset[str] = frozenset()
    if has_female and not has_male:
        _gender_block = _MALE_ONLY_TAGS
    elif has_male and not has_female:
        _gender_block = _FEMALE_ONLY_TAGS

    # Merge: 동일 e621 태그는 max score 유지
    merged: dict[str, tuple[float, str, str]] = {}
    for tag_us in tags:
        entries = _BOOST_MAP.get(tag_us)
        if not entries:
            continue
        if tag_us in _SOURCE_BLOCKLIST:
            continue
        for e621_tag, score, cat in entries:
            # Output blocklist
            if e621_tag in _OUTPUT_BLOCKLIST:
                continue
            # Score floor
            if score < score_floor:
                continue
            # Explicit context gate: 비-explicit 프롬프트에서는 safe 카테고리만 허용
            if not is_explicit and cat not in _SAFE_CATEGORIES:
                continue
            # Gender context gate: 성별 모순 태그 차단
            if e621_tag in _gender_block:
                continue
            # Noise tag jumper: 화이트리스트에 없으면 DROP
            if e621_tag in _NOISE_TAGS:
                allowed = _NOISE_WHITELIST.get(e621_tag)
                if not allowed or tag_us not in allowed:
                    continue
            # Anchor gate: 도메인 특화 태그의 맥락 검증
            if not _check_anchor_gate(e621_tag, tags_set):
                continue
            # Domain gate: keyword split으로 잡히지 않는 도메인 (scat 등)
            if not _check_domain_gate(e621_tag, tags_set):
                continue
            if _check_pair_block(e621_tag, tag_us):
                continue
            # Characteristic filter: 외형 태그는 단어 겹침 있을 때만 허용
            if not _check_characteristic_filter(tag_us, e621_tag):
                continue
            # Single-source gate: 단독 source + 단어 무관 output은 whitelist 필요
            if not _check_single_source_gate(tag_us, e621_tag):
                continue
            if e621_tag not in merged or score > merged[e621_tag][0]:
                merged[e621_tag] = (score, cat, tag_us.replace("_", " "))

    # Sort by score descending
    sorted_all = sorted(merged.items(), key=lambda x: -x[1][0])
    sorted_all = _dedupe_group_results(sorted_all, mode=mode)

    # Source-keyword dedup: 동일 키워드(4자+) 공유 시 상위 _SKD_CAP개만 유지
    skd_counts: dict[str, int] = {}
    skd_filtered: list[tuple[str, tuple[float, str, str]]] = []
    for e621_tag, payload in sorted_all:
        src_us = payload[2].replace(" ", "_")
        src_words = {w for w in src_us.split("_") if len(w) >= 4}
        tag_words = {w for w in e621_tag.split("_") if len(w) >= 4}
        shared = src_words & tag_words
        if shared:
            blocked = False
            for kw in shared:
                skd_counts[kw] = skd_counts.get(kw, 0) + 1
                if skd_counts[kw] > _SKD_CAP:
                    blocked = True
            if blocked:
                continue
        skd_filtered.append((e621_tag, payload))
    sorted_all = skd_filtered

    # Diversity cap
    if diversity_cap > 0:
        cat_counts: dict[str, int] = {}
        filtered: list[tuple[str, float, str, str]] = []
        for e621_tag, (score, cat, src) in sorted_all:
            cat_counts[cat] = cat_counts.get(cat, 0) + 1
            if cat_counts[cat] <= diversity_cap:
                filtered.append((e621_tag, score, cat, src))
            if len(filtered) >= top_n:
                break
        return filtered

    return [(tag, s, c, src) for tag, (s, c, src) in sorted_all[:top_n]]


def get_sources() -> list[str]:
    """등록된 모든 source 태그 반환."""
    return sorted(_BOOST_MAP.keys())


def has_source(tag: str) -> bool:
    """해당 태그가 source로 등록되어 있는지 확인."""
    return tag.replace(" ", "_") in _BOOST_MAP


if __name__ == "__main__":
    # Quick test
    for prompt in [
        "doggystyle, ahegao, sweat",
        "straddling, blush, smile",
        "bestiality, tears, restrained",
        "standing sex, clothed sex, saliva",
    ]:
        tags = recommend(prompt, top_n=5)
        print(f"{prompt}")
        print(f"  → {tags}")
        print()
